// Measure TTFB using Navigation Timing API
const perfData = performance.getEntriesByType('navigation')[0];
const ttfb = perfData.responseStart - perfData.requestStart;

console.log('TTFB:', ttfb, 'ms');

// Break down TTFB components
const dnsTime = perfData.domainLookupEnd - perfData.domainLookupStart;
const tcpTime = perfData.connectEnd - perfData.connectStart;
const tlsTime = perfData.secureConnectionStart > 0 ? 
  perfData.connectEnd - perfData.secureConnectionStart : 0;
const serverTime = perfData.responseStart - perfData.requestStart;

console.log('DNS:', dnsTime, 'TCP:', tcpTime, 'TLS:', tlsTime, 'Server:', serverTime);

