// Example budget calculation for 3G network
const network3G = {
  rtt: 300, // Round-trip time in ms
  throughput: 1.6 * 1024 * 1024, // 1.6 Mbps in bytes
};

// Target: 3 second load time
const targetLoadTime = 3000; // 3 seconds
const overhead = network3G.rtt * 2; // TCP handshake overhead
const availableTime = targetLoadTime - overhead;

// Calculate max bundle size
const maxBundleSize = Math.floor(
  (network3G.throughput * availableTime) / 1000 / 8
);

console.log('Max bundle size:', maxBundleSize, 'bytes');
