// scripts/check-performance-budget.js
const lighthouse = require('lighthouse');
const chromeLauncher = require('chrome-launcher');

const BUDGETS = {
  'total-byte-weight': 1000 * 1024, // 1MB total
  'script-count': 10, // Max 10 scripts
  'largest-contentful-paint': 2500, // 2.5s LCP
};

async function checkBudgets(url) {
  const chrome = await chromeLauncher.launch({ chromeFlags: ['--headless'] });
  const options = { logLevel: 'info', output: 'json', port: chrome.port };
  const runnerResult = await lighthouse(url, options);

  const audits = runnerResult.lhr.audits;
  let failed = false;

  for (const [metric, budget] of Object.entries(BUDGETS)) {
    const actual = audits[metric]?.numericValue;
    if (actual > budget) {
      console.error(`❌ ${metric}: ${actual} exceeds budget ${budget}`);
      failed = true;
    } else {
      console.log(`✅ ${metric}: ${actual} within budget ${budget}`);
    }
  }

  await chrome.kill();
  process.exit(failed ? 1 : 0);
}

checkBudgets('http://localhost:3000');
